/*
 * kor-AssetForge service worker.
 *
 * Hand-written rather than generated by a Workbox/Serwist plugin: those
 * plugins hook into webpack, while this app builds with Turbopack.
 *
 * Strategies:
 *   - Navigations (HTML pages):    network-first, cached copy, then /offline.html
 *   - Next build assets (/_next/static, hashed and immutable): cache-first
 *   - Other same-origin static files (icons, fonts, images): stale-while-revalidate
 *   - API calls, cross-origin requests and non-GET requests: never cached, so
 *     balances, orders and wallet data are always live.
 *
 * Bump CACHE_VERSION whenever the caching rules or precache list change; old
 * caches are removed on activate.
 */

const CACHE_VERSION = "v1";
const PRECACHE = `kor-precache-${CACHE_VERSION}`;
const RUNTIME = `kor-runtime-${CACHE_VERSION}`;
const OFFLINE_URL = "/offline.html";

const PRECACHE_URLS = [
  OFFLINE_URL,
  "/icon-192.png",
  "/icon-512.png",
  "/apple-touch-icon.png",
  "/manifest.webmanifest",
];

/** Keep the runtime cache from growing without bound. */
const MAX_RUNTIME_ENTRIES = 120;

self.addEventListener("install", (event) => {
  event.waitUntil(
    caches
      .open(PRECACHE)
      .then((cache) => cache.addAll(PRECACHE_URLS))
      .then(() => self.skipWaiting()),
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      const keep = new Set([PRECACHE, RUNTIME]);
      const keys = await caches.keys();
      await Promise.all(
        keys
          .filter((key) => key.startsWith("kor-") && !keep.has(key))
          .map((key) => caches.delete(key)),
      );
      if (self.registration.navigationPreload) {
        await self.registration.navigationPreload.enable();
      }
      await self.clients.claim();
    })(),
  );
});

// Lets the page activate a waiting worker after the user accepts an update.
self.addEventListener("message", (event) => {
  if (event.data && event.data.type === "SKIP_WAITING") {
    self.skipWaiting();
  }
});

async function trimCache(cacheName, maxEntries) {
  const cache = await caches.open(cacheName);
  const keys = await cache.keys();
  if (keys.length <= maxEntries) return;
  await Promise.all(
    keys.slice(0, keys.length - maxEntries).map((key) => cache.delete(key)),
  );
}

async function putInCache(request, response) {
  // Only cache complete, same-origin, successful responses.
  // Redirected responses can't be replayed for navigations, so skip them too.
  if (
    !response ||
    response.status !== 200 ||
    response.type !== "basic" ||
    response.redirected
  ) {
    return;
  }
  const cache = await caches.open(RUNTIME);
  await cache.put(request, response);
  trimCache(RUNTIME, MAX_RUNTIME_ENTRIES);
}

async function handleNavigation(event) {
  try {
    const preloaded = await event.preloadResponse;
    const response = preloaded || (await fetch(event.request));
    event.waitUntil(putInCache(event.request, response.clone()));
    return response;
  } catch {
    const cached = await caches.match(event.request);
    if (cached) return cached;
    const offline = await caches.match(OFFLINE_URL);
    return (
      offline ||
      new Response("You are offline.", {
        status: 503,
        headers: { "Content-Type": "text/plain; charset=utf-8" },
      })
    );
  }
}

async function cacheFirst(request) {
  const cached = await caches.match(request);
  if (cached) return cached;
  const response = await fetch(request);
  await putInCache(request, response.clone());
  return response;
}

async function staleWhileRevalidate(event) {
  const cached = await caches.match(event.request);
  const network = fetch(event.request)
    .then(async (response) => {
      await putInCache(event.request, response.clone());
      return response;
    })
    .catch(() => undefined);

  if (cached) {
    event.waitUntil(network);
    return cached;
  }
  const response = await network;
  return response || Response.error();
}

self.addEventListener("fetch", (event) => {
  const { request } = event;
  if (request.method !== "GET") return;

  const url = new URL(request.url);
  // Wallet extensions, Horizon, the backend API and other origins are live data.
  if (url.origin !== self.location.origin) return;
  if (url.pathname.startsWith("/api/")) return;
  // Dev server internals and React Server Component payloads change per request.
  if (url.pathname.startsWith("/_next/webpack-hmr")) return;
  if (request.headers.get("RSC") === "1") return;

  if (request.mode === "navigate") {
    event.respondWith(handleNavigation(event));
    return;
  }

  if (url.pathname.startsWith("/_next/static/")) {
    event.respondWith(cacheFirst(request));
    return;
  }

  if (
    ["style", "script", "font", "image"].includes(request.destination) ||
    /\.(?:png|jpg|jpeg|gif|svg|webp|ico|woff2?)$/i.test(url.pathname)
  ) {
    event.respondWith(staleWhileRevalidate(event));
  }
});
